mapper.select:
SELECT * FROM ( SELECT record.primary_key, 'money' as record_type, record.applicant, record.apply_time, record.record_amount as amount, record.currency, record.confirmed_exchange_rate, record.remark, record.final_approve, record.confirm_time, record.reject_reason, record.reject_time, record.approval_status, record.signed_contract, record.contract_number, record.payment_time, record.enterprise_code, contract.counterpart AS opposite, contract.contract AS contract_code, record.create_time FROM ${moneyTableName} record INNER JOIN ${signedContractTable} contract ON record.signed_contract = contract.primary_key WHERE record.enterprise_code = #{enterpriseCode} AND record.delete_flag = 'f' AND contract.identity = 't' AND contract.canceled = 'f'
AND contract.counterpart LIKE '%'|| #{opposite} ||'%'
AND record.contract_number LIKE '%'|| #{contractNumber} ||'%'
AND record.applicant IN
#{applicant}
AND record.applicant IN
#{staffCode}
AND record.approval_status IN
#{approveState}
AND record.apply_time IS NOT NULL AND record.apply_time >= #{applyTimePre}
AND record.apply_time IS NOT NULL AND record.apply_time <= #{applyTimePost}
UNION ALL
SELECT record.primary_key, 'invoice' as record_type, record.applicant, record.apply_time, record.invoice_amount as amount, NULL as currency, NULL as confirmed_exchange_rate, record.remark, record.final_approve, record.confirm_time, record.reject_reason, record.reject_time, record.approval_status, record.signed_contract, record.contract_number, NULL as payment_time, record.enterprise_code, contract.counterpart AS opposite, contract.contract AS contract_code, record.create_time FROM ${invoiceTableName} record INNER JOIN ${signedContractTable} contract ON record.signed_contract = contract.primary_key WHERE record.enterprise_code = #{enterpriseCode} AND record.delete_flag = 'f' AND contract.identity = 't' AND contract.canceled = 'f'
AND contract.counterpart LIKE '%'|| #{opposite} ||'%'
AND record.contract_number LIKE '%'|| #{contractNumber} ||'%'
AND record.applicant IN
#{applicant}
AND record.applicant IN
#{staffCode}
AND record.approval_status IN
#{approveState}
AND record.apply_time IS NOT NULL AND record.apply_time >= #{applyTimePre}
AND record.apply_time IS NOT NULL AND record.apply_time <= #{applyTimePost}
) combined_records ORDER BY combined_records.create_time DESC
